parts.text:
{
  "judgments": [
    {
      "proposal_id": "P0000",
      "quotes": [
        "(a) Except as provided in paragraph (b) of this section, the driver of a commercial motor vehicle specified in paragraphs (a) (1) through (6) of this section shall not cross a railroad track or tracks at grade unless he/she first: Stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks",
        "(b) A stop need not be made at:\n\n(1) A streetcar crossing, or railroad tracks used exclusively for industrial switching purposes, within a business district, as defined in § 390.5 of this chapter."
      ],
      "rationale": "Paragraph (a) introduces the stopping requirement with the caveat 'Except as provided in paragraph (b) of this section', and paragraph (b)(1) specifies that a stop need not be made at streetcar crossings or industrial switching tracks within a business district. Linking C0009 to baseline duty C0000 with an exception relation accurately reflects this structural qualification.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0001",
      "quotes": [
        "(a) Except as provided in paragraph (b) of this section, the driver of a commercial motor vehicle specified in paragraphs (a) (1) through (6) of this section shall not cross a railroad track or tracks at grade unless he/she first: Stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks",
        "(b) A stop need not be made at:\n\n(1) A streetcar crossing, or railroad tracks used exclusively for industrial switching purposes, within a business district, as defined in § 390.5 of this chapter.\n\n(2) A railroad grade crossing when a police officer or crossing flagman directs traffic to proceed."
      ],
      "rationale": "Paragraph (b)(2) explicitly exempts commercial motor vehicle drivers from making the paragraph (a) stop when directed to proceed by a police officer or crossing flagman. Updating C0010 to qualify baseline C0000 as an exception correctly captures this explicit regulatory caveat.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0002",
      "quotes": [
        "(a) Except as provided in paragraph (b) of this section, the driver of a commercial motor vehicle specified in paragraphs (a) (1) through (6) of this section shall not cross a railroad track or tracks at grade unless he/she first: Stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks",
        "(b) A stop need not be made at:\n\n(1) A streetcar crossing, or railroad tracks used exclusively for industrial switching purposes, within a business district, as defined in § 390.5 of this chapter.\n\n(2) A railroad grade crossing when a police officer or crossing flagman directs traffic to proceed.\n\n(3) A railroad grade crossing controlled by a functioning highway traffic signal transmitting a green indication which, under local law, permits the commercial motor vehicle to proceed across the railroad tracks without slowing or stopping."
      ],
      "rationale": "Paragraph (b)(3) provides that a stop need not be made at crossings controlled by a functioning green signal allowing crossing without slowing or stopping under local law. Setting relation to exception and qualifies to C0000 correctly models this exception to the general stopping requirement.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0003",
      "quotes": [
        "(a) Except as provided in paragraph (b) of this section, the driver of a commercial motor vehicle specified in paragraphs (a) (1) through (6) of this section shall not cross a railroad track or tracks at grade unless he/she first: Stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks",
        "(b) A stop need not be made at:\n\n(1) A streetcar crossing, or railroad tracks used exclusively for industrial switching purposes, within a business district, as defined in § 390.5 of this chapter.\n\n(2) A railroad grade crossing when a police officer or crossing flagman directs traffic to proceed.\n\n(3) A railroad grade crossing controlled by a functioning highway traffic signal transmitting a green indication which, under local law, permits the commercial motor vehicle to proceed across the railroad tracks without slowing or stopping.\n\n(4) An abandoned railroad grade crossing which is marked with a sign indicating that the rail line is abandoned."
      ],
      "rationale": "Paragraph (b)(4) specifies that a stop need not be made at marked abandoned railroad grade crossings, qualifying the mandatory stopping baseline in paragraph (a) (C0000). Adding the qualifies link to C0000 with an exception relation is fully supported.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0004",
      "quotes": [
        "(a) Except as provided in paragraph (b) of this section, the driver of a commercial motor vehicle specified in paragraphs (a) (1) through (6) of this section shall not cross a railroad track or tracks at grade unless he/she first: Stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks",
        "(b) A stop need not be made at:\n\n(1) A streetcar crossing, or railroad tracks used exclusively for industrial switching purposes, within a business district, as defined in § 390.5 of this chapter.\n\n(2) A railroad grade crossing when a police officer or crossing flagman directs traffic to proceed.\n\n(3) A railroad grade crossing controlled by a functioning highway traffic signal transmitting a green indication which, under local law, permits the commercial motor vehicle to proceed across the railroad tracks without slowing or stopping.\n\n(4) An abandoned railroad grade crossing which is marked with a sign indicating that the rail line is abandoned.\n\n(5) An industrial or spur line railroad grade crossing marked with a sign reading “Exempt.” Such “Exempt” signs shall be erected only by or with the consent of the appropriate State or local authority."
      ],
      "rationale": "Paragraph (b)(5) excuses the stopping requirement at industrial or spur line crossings marked 'Exempt'. Connecting C0013 to C0000 as an exception faithfully represents the statutory structure of the rule.",
      "verdict": "supported"
    }
  ]
}
